//! gfx1151 machine model: shader-cycle latencies and issue costs per
//! instruction class, measured on gfx1151 with in-kernel counters
//! (SHADER_CYCLES and REALTIME) by the model agent's microbenchmarks.
//!
//! Generated by `gen_model.py` from `gfx1151_model.json` (model agent's out
//! folder); do not edit by hand. Proposed and not wired in: nothing in the
//! compile path uses this module. `result_latency` is a drop-in replacement for
//! the function of the same name in `post.rs`; `unit` and `issue_cycles` are
//! for a scheduler that also models resource occupancy.
//!
//! Conventions: `latency` is the number of cycles from the producer's issue to
//! the first cycle a dependent instruction can issue without stalling;
//! `issue` is the number of cycles an instruction occupies its unit on one
//! SIMD when several waves are resident. Memory latencies are at the top
//! shader clock.

use super::mir::*;

/// The execution resource an instruction occupies.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Unit {
    /// Scalar ALU.
    Salu,
    /// Scalar memory (kernel arguments, constants).
    Smem,
    /// Full-rate vector ALU.
    Valu,
    /// Quarter-rate integer multiplies (`v_mul_lo/hi_u32`, `v_mad_u64_u32`).
    ValuQuarter,
    /// Half-rate 64-bit shifts.
    ValuHalf,
    /// Double precision (1/32 rate).
    ValuF64,
    /// Transcendental unit (`v_exp`, `v_log`, `v_rcp`, `v_rsq`, `v_sqrt`).
    Trans,
    /// DPP moves and permlanes.
    Xlane,
    /// The per-SIMD WMMA unit: one 16x16x16 at a time, other waves keep issuing.
    Wmma,
    /// LDS loads, stores, swizzles and permutes.
    Lds,
    /// Vector memory loads (global, buffer, scratch).
    VmemLoad,
    /// Vector memory stores and atomics without return.
    VmemStore,
    /// Branches, waits, hints and pseudos.
    Control,
}

/// Latency and issue cost of a class, in shader cycles.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Cost {
    pub latency: u32,
    pub issue: u32,
}

// Classes: latency to a dependent instruction and issue cycles per SIMD.
/// Full-rate VALU (f32, f16, packed f16, integer, conversions, `v_fma_mix`, `v_dot2`).
pub const VALU: Cost = Cost { latency: 5, issue: 1 };
/// `v_cvt_f16_f32`.
pub const VALU_CVT_F16: Cost = Cost { latency: 6, issue: 1 };
/// Quarter-rate integer multiplies.
pub const VALU_QUARTER: Cost = Cost { latency: 8, issue: 4 };
/// 64-bit shifts.
pub const VALU_HALF64: Cost = Cost { latency: 6, issue: 2 };
/// Double precision.
pub const VALU_F64: Cost = Cost { latency: 38, issue: 32 };
/// Transcendentals.
pub const TRANS: Cost = Cost { latency: 10, issue: 4 };
/// DPP moves.
pub const XLANE_DPP: Cost = Cost { latency: 7, issue: 3 };
/// `v_permlane16_b32` / `v_permlanex16_b32`.
pub const XLANE_PERMLANE: Cost = Cost { latency: 6, issue: 3 };
/// 16x16x16 WMMA (f16, bf16, iu8): latency to a VALU reader; the issue cost is the
/// per-SIMD unit occupancy (several waves do not overlap WMMAs, but other
/// waves' VALU, SALU, LDS and TRANS issue meanwhile).
pub const WMMA: Cost = Cost { latency: 36, issue: 34 };
/// 16x16x16 iu4 WMMA.
pub const WMMA_IU4: Cost = Cost { latency: 20, issue: 18 };
/// SALU.
pub const SALU: Cost = Cost { latency: 2, issue: 1 };
/// `s_mul_i32` / `s_mul_hi_*`.
pub const SALU_MUL: Cost = Cost { latency: 3, issue: 2 };
/// Scalar loads hitting the scalar cache (b32..b256).
pub const SMEM: Cost = Cost { latency: 30, issue: 5 };
/// LDS loads (b32, u16, u8): latency is the wait release.
pub const LDS_LOAD: Cost = Cost { latency: 32, issue: 4 };
/// LDS stores.
pub const LDS_STORE: Cost = Cost { latency: 32, issue: 4 };
/// `ds_bpermute_b32` / `ds_permute_b32`.
pub const LDS_XLANE: Cost = Cost { latency: 36, issue: 4 };
/// Vector memory loads when the level is unknown (L2 / MALL hit).
pub const VMEM_LOAD: Cost = Cost { latency: 382, issue: 5 };
/// Vector memory stores (no result).
pub const VMEM_STORE: Cost = Cost { latency: 0, issue: 17 };

/// Scalar `s_load_b512` hit latency.
pub const SMEM_B512_LATENCY: u32 = 33;
/// Scalar load missing the scalar cache.
pub const SMEM_MISS_LATENCY: u32 = 340;
/// LDS b64 and b128 load latencies (wait release).
pub const LDS_LOAD_B64_LATENCY: u32 = 34;
pub const LDS_LOAD_B128_LATENCY: u32 = 38;
/// LDS b128 issue cycles (one wave): load, store.
pub const LDS_LOAD_B128_ISSUE: u32 = 6;
pub const LDS_STORE_B128_ISSUE: u32 = 5;
/// LDS banks and bank width; LDS bandwidth per WGP (shared by its 4 SIMDs).
pub const LDS_BANKS: u32 = 32;
pub const LDS_BANK_BYTES: u32 = 4;
pub const LDS_WGP_BYTES_PER_CYCLE: u32 = 133;
/// Vector load latency by the level that hits (top clock).
pub const VMEM_L0_LATENCY: u32 = 73;
pub const VMEM_L1_LATENCY: u32 = 120;
pub const VMEM_L2_LATENCY: u32 = 382;
pub const VMEM_DRAM_LATENCY: u32 = 520;
/// Vector memory b128 issue cycles (one wave): load, store, and a store
/// whose lanes write half of each 32-byte chunk (needs a store clause to merge).
pub const VMEM_LOAD_B128_ISSUE: u32 = 7;
pub const VMEM_STORE_B128_ISSUE: u32 = 23;
pub const VMEM_STORE_B128_HALF_LINES_ISSUE: u32 = 32;
/// Extra cycles before a VALU can read a load's result after the wait releases.
pub const LOAD_USE_EXTRA: u32 = 12;
/// A VALU-written SGPR read by SALU (v_cmp -> s_and), against 5 for a VALU reader.
pub const VALU_TO_SALU: u32 = 18;
/// `v_readfirstlane_b32` result to a VALU reader.
pub const READFIRSTLANE_TO_VALU: u32 = 6;
/// Issue cycles of an `s_waitcnt` whose counters are already satisfied.
pub const WAITCNT_IDLE_ISSUE: u32 = 1;
/// Instruction cache bytes; a single wave's fetch slows well before it fills.
pub const ICACHE_BYTES: u32 = 32768;
/// Waves per SIMD at which independent VALU reaches full issue rate, and at
/// which a dependent chain with `s_delay_alu` hints does (without hints a
/// dependent chain saturates at a third of the issue rate).
pub const VALU_PEAK_WAVES: u32 = 4;
pub const VALU_DEP_PEAK_WAVES_WITH_HINTS: u32 = 8;

/// The unit `op` occupies.
pub fn unit(op: Opc) -> Unit {
    let flags = op.flags();
    match op {
        Opc::VMulLoU32 | Opc::VMulHiU32 | Opc::VMulHiI32 | Opc::VMadU64U32 | Opc::VMadI64I32 => Unit::ValuQuarter,
        Opc::VLshlrevB64 | Opc::VLshrrevB64 | Opc::VAshrrevI64 => Unit::ValuHalf,
        Opc::VFmaF64 | Opc::VAddF64 | Opc::VMulF64 | Opc::VMaxF64 => Unit::ValuF64,
        Opc::VMovB32Dpp | Opc::VMovB32Dpp8 | Opc::VPermlane16B32 | Opc::VPermlanex16B32 => Unit::Xlane,
        Opc::SWaitcntVscnt => Unit::Control,
        _ if flags & F_WMMA != 0 => Unit::Wmma,
        _ if flags & F_TRANS != 0 => Unit::Trans,
        _ if flags & F_LDS != 0 => Unit::Lds,
        _ if flags & F_SMEM != 0 => Unit::Smem,
        _ if flags & F_VMEM_LOAD != 0 => Unit::VmemLoad,
        _ if flags & F_VMEM_STORE != 0 => Unit::VmemStore,
        _ => match op.fmt() {
            Fmt::Sop1 | Fmt::Sop2 | Fmt::Sopc | Fmt::Sopk => Unit::Salu,
            Fmt::Vop1 | Fmt::Vop2 | Fmt::Vop3 | Fmt::Vop3b | Fmt::Vopc | Fmt::Vop3p | Fmt::Vopd => Unit::Valu,
            _ => Unit::Control,
        },
    }
}

/// Bytes moved by an LDS or vector-memory access of `op` per lane.
fn access_dwords(op: Opc) -> u32 {
    let name = op.name();
    if name.ends_with("b128") {
        4
    } else if name.ends_with("b96") {
        3
    } else if name.ends_with("b64") {
        2
    } else {
        1
    }
}

/// Cycles from issue until a dependent instruction can issue (drop-in for
/// `post.rs`'s `result_latency`). Loads count the wait release plus the extra
/// cycles before a VALU can read the returned data.
pub fn result_latency(inst: &MInst) -> u32 {
    let op = inst.op;
    if op.fmt() == Fmt::Pseudo && op.flags() & F_USE_EXEC == 0 {
        return 0;
    }
    match unit(op) {
        Unit::VmemLoad => VMEM_LOAD.latency + LOAD_USE_EXTRA,
        Unit::Lds => {
            let base = match access_dwords(op) {
                4 => LDS_LOAD_B128_LATENCY,
                2 | 3 => LDS_LOAD_B64_LATENCY,
                _ => LDS_LOAD.latency,
            };
            let xlane = matches!(op, Opc::DsBpermuteB32) as u32 * LDS_XLANE.latency.saturating_sub(LDS_LOAD.latency);
            base + xlane + LOAD_USE_EXTRA
        }
        Unit::Smem => {
            if op == Opc::SLoadB512 {
                SMEM_B512_LATENCY
            } else {
                SMEM.latency
            }
        }
        Unit::Wmma => match op {
            Opc::VWmmaI32Iu4 | Opc::VWmmaI32Iu4Early => WMMA_IU4.latency,
            _ => WMMA.latency,
        },
        Unit::Trans => TRANS.latency,
        Unit::ValuQuarter => VALU_QUARTER.latency,
        Unit::ValuHalf => VALU_HALF64.latency,
        Unit::ValuF64 => VALU_F64.latency,
        Unit::Xlane => match op {
            Opc::VMovB32Dpp | Opc::VMovB32Dpp8 => XLANE_DPP.latency,
            _ => XLANE_PERMLANE.latency,
        },
        Unit::Salu => match op {
            Opc::SMulI32 | Opc::SMulHiU32 | Opc::SMulHiI32 => SALU_MUL.latency,
            _ => SALU.latency,
        },
        Unit::Valu => match op {
            Opc::VCvtF16F32 => VALU_CVT_F16.latency,
            Opc::VReadfirstlaneB32 | Opc::VReadlaneB32 => READFIRSTLANE_TO_VALU,
            _ => VALU.latency,
        },
        Unit::VmemStore | Unit::Control => 0,
    }
}

/// Extra cycles when the consumer of a VALU-written SGPR is a SALU
/// instruction (the VALU-to-SALU path is much slower than VALU-to-VALU).
pub fn sgpr_consumer_extra(producer: &MInst, consumer: &MInst) -> u32 {
    let to_salu = unit(consumer.op) == Unit::Salu;
    let from_valu = matches!(unit(producer.op), Unit::Valu | Unit::ValuQuarter | Unit::Trans);
    if to_salu && from_valu {
        VALU_TO_SALU.saturating_sub(VALU.latency)
    } else {
        0
    }
}

/// Cycles `inst` occupies its unit on one SIMD (several waves resident).
pub fn issue_cycles(inst: &MInst) -> u32 {
    let op = inst.op;
    match unit(op) {
        Unit::Wmma => match op {
            Opc::VWmmaI32Iu4 | Opc::VWmmaI32Iu4Early => WMMA_IU4.issue,
            _ => WMMA.issue,
        },
        Unit::Trans => TRANS.issue,
        Unit::ValuQuarter => VALU_QUARTER.issue,
        Unit::ValuHalf => VALU_HALF64.issue,
        Unit::ValuF64 => VALU_F64.issue,
        Unit::Xlane => XLANE_DPP.issue,
        Unit::Lds => {
            if inst.defs.is_empty() {
                if access_dwords(op) == 4 {
                    LDS_STORE_B128_ISSUE
                } else {
                    LDS_STORE.issue
                }
            } else if access_dwords(op) == 4 {
                LDS_LOAD_B128_ISSUE
            } else {
                LDS_LOAD.issue
            }
        }
        Unit::VmemLoad => {
            if access_dwords(op) == 4 {
                VMEM_LOAD_B128_ISSUE
            } else {
                VMEM_LOAD.issue
            }
        }
        Unit::VmemStore => {
            if access_dwords(op) == 4 {
                VMEM_STORE_B128_ISSUE
            } else {
                VMEM_STORE.issue
            }
        }
        Unit::Smem => SMEM.issue,
        Unit::Salu => match op {
            Opc::SMulI32 | Opc::SMulHiU32 | Opc::SMulHiI32 => SALU_MUL.issue,
            _ => SALU.issue,
        },
        Unit::Valu => VALU.issue,
        Unit::Control => match op {
            Opc::SWaitcnt | Opc::SWaitcntExplicit | Opc::SWaitcntVscnt => WAITCNT_IDLE_ISSUE,
            Opc::SNop => inst.imm as u32 + 1,
            _ => 0,
        },
    }
}

/// Issue cycles of one LDS b32 access whose 32 lanes use `stride` dwords
/// between consecutive lanes (32 banks of 4 bytes): the bank-conflict degree,
/// or the conflict-free issue cost if larger.
pub fn lds_b32_issue_for_stride(stride: u32) -> u32 {
    if stride == 0 {
        return LDS_LOAD.issue;
    }
    let banks_used = LDS_BANKS / gcd(stride % LDS_BANKS, LDS_BANKS).max(1);
    let degree = 32 / banks_used.min(32).max(1);
    degree.max(LDS_LOAD.issue)
}

fn gcd(a: u32, b: u32) -> u32 {
    if a == 0 {
        b
    } else {
        gcd(b % a, a)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn inst(op: Opc) -> MInst {
        MInst::new(op, [], [])
    }

    #[test]
    fn classes_cover_the_opcodes_the_scheduler_sees() {
        assert_eq!(unit(Opc::VAddF32), Unit::Valu);
        assert_eq!(unit(Opc::VExpF32), Unit::Trans);
        assert_eq!(unit(Opc::VWmmaF32F16), Unit::Wmma);
        assert_eq!(unit(Opc::VWmmaF32Bf16Early), Unit::Wmma);
        assert_eq!(unit(Opc::DsLoadB128), Unit::Lds);
        assert_eq!(unit(Opc::GLoadB128), Unit::VmemLoad);
        assert_eq!(unit(Opc::GStoreB128), Unit::VmemStore);
        assert_eq!(unit(Opc::SLoadB64), Unit::Smem);
        assert_eq!(unit(Opc::SAddU32), Unit::Salu);
        assert_eq!(unit(Opc::VMadU64U32), Unit::ValuQuarter);
        assert_eq!(unit(Opc::SBranch), Unit::Control);
    }

    #[test]
    fn latencies_are_ordered_as_measured() {
        let l = |op| result_latency(&inst(op));
        assert!(l(Opc::SAddU32) < l(Opc::VAddF32));
        assert!(l(Opc::VAddF32) < l(Opc::VExpF32));
        assert!(l(Opc::VExpF32) < l(Opc::VWmmaF32F16));
        assert!(l(Opc::DsLoadB32) < l(Opc::DsLoadB128));
        assert!(l(Opc::DsLoadB128) < l(Opc::GLoadB32));
        assert_eq!(l(Opc::Copy), 0);
    }

    #[test]
    fn wmma_occupies_its_unit_longer_than_any_alu() {
        let i = |op| issue_cycles(&inst(op));
        assert!(i(Opc::VWmmaF32F16) > i(Opc::VFmaF64));
        assert!(i(Opc::VWmmaI32Iu4) < i(Opc::VWmmaF32F16));
        assert_eq!(i(Opc::VAddF32), 1);
    }

    #[test]
    fn lds_strides_conflict_by_powers_of_two() {
        assert_eq!(lds_b32_issue_for_stride(32), 32);
        assert_eq!(lds_b32_issue_for_stride(16), 16);
        assert_eq!(lds_b32_issue_for_stride(8), 8);
        assert_eq!(lds_b32_issue_for_stride(33), LDS_LOAD.issue);
        assert_eq!(lds_b32_issue_for_stride(1), LDS_LOAD.issue);
    }

    #[test]
    fn valu_to_salu_costs_more_than_valu_to_valu() {
        let cmp = inst(Opc::VCmp(0x44));
        assert!(sgpr_consumer_extra(&cmp, &inst(Opc::SAndB32)) > 0);
        assert_eq!(sgpr_consumer_extra(&cmp, &inst(Opc::VCndmaskB32)), 0);
    }
}
